result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/supershape.js", "content": "import * as THREE from 'three';

/**
 * Gielis' superformula (1997), the generalization of the superellipse:
 *
 *   r(angle) = ( |cos(m*angle/4)/a|^n2 + |sin(m*angle/4)/b|^n3 )^(-1/n1)
 *
 * With m = 0 the angle terms vanish: cos(0) = 1, sin(0) = 0, so the inner
 * sum is the constant a^(-n2) and
 *
 *   r = (a^(-n2)) ^ (-1/n1) = a^(n2/n1)   // documented constant C
 *
 * i.e. for a = b = 1, n1 = n2 = n3 = 1 the radius is the constant 1
 * (= 2^(-1) times the constant 2 that appears when both terms are kept),
 * independent of `angle`.
 *
 * @param {number} angle - Angle in radians.
 * @param {object} p - Shape parameters.
 * @param {number} p.m  - Symmetry / number of lobes.
 * @param {number} p.n1 - Exponent controlling pinching/spikiness.
 * @param {number} p.n2 - Exponent on the cosine term.
 * @param {number} p.n3 - Exponent on the sine term.
 * @param {number} [p.a=1]
 * @param {number} [p.b=1]
 * @returns {number} Radius at `angle`.
 */
export function superRadius(angle, { m, n1, n2, n3, a = 1, b = 1 }) {
  const t = (m * angle) / 4;
  const term =
    Math.abs(Math.cos(t) / a) ** n2 + Math.abs(Math.sin(t) / b) ** n3;
  return Math.pow(term, -1 / n1);
}

/**
 * Sweep two superformula profiles into the standard spherical product:
 *
 *   x(theta, phi) = rTheta(theta)*cos(theta) * rPhi(phi)*cos(phi)
 *   y(theta, phi) = rTheta(theta)*sin(theta)
 *   z(theta, phi) = rTheta(theta)*cos(theta) * rPhi(phi)*sin(phi)
 *
 * with theta in [-PI/2, PI/2] and phi in [-PI, PI].
 *
 * The mesh is non-indexed: a grid of (segs+1)^2 profile points is emitted as
 * segs*segs quads, each split into 2 triangles = 6 vertices. Therefore the
 * position attribute holds exactly
 *
 *   vertexCount = 6 * segs * segs
 *
 * vertices. Normals are computed via computeVertexNormals().
 *
 * @param {object} paramsTheta - Superformula params for the theta sweep.
 * @param {object} paramsPhi   - Superformula params for the phi sweep.
 * @param {object} [opts]
 * @param {number} [opts.segs=96] - Segments per axis.
 * @returns {THREE.BufferGeometry}
 */
export function buildSupershape(paramsTheta, paramsPhi, { segs = 96 } = {}) {
  // Precompute the (segs+1) x (segs+1) grid of points.
  const grid = new Array(segs + 1);
  for (let i = 0; i <= segs; i++) {
    const theta = -Math.PI / 2 + (Math.PI * i) / segs;
    const cosT = Math.cos(theta);
    const sinT = Math.sin(theta);
    const rt = superRadius(theta, paramsTheta);

    const row = new Array(segs + 1);
    for (let j = 0; j <= segs; j++) {
      const phi = -Math.PI + (2 * Math.PI * j) / segs;
      const rp = superRadius(phi, paramsPhi);
      row[j] = [
        rt * cosT * rp * Math.cos(phi), // x
        rt * sinT,                      // y
        rt * cosT * rp * Math.sin(phi), // z
      ];
    }
    grid[i] = row;
  }

  // Emit non-indexed triangles (two per quad).
  const positions = new Float32Array(6 * segs * segs * 3);
  let k = 0;
  for (let i = 0; i < segs; i++) {
    for (let j = 0; j < segs; j++) {
      for (const [a, c, d] of [
        [grid[i][j], grid[i][j + 1], grid[i + 1][j]],
        [grid[i + 1][j], grid[i][j + 1], grid[i + 1][j + 1]],
      ]) {
        for (const v of [a, c, d]) {
          positions[k++] = v[0];
          positions[k++] = v[1];
          positions[k++] = v[2];
        }
      }
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.computeVertexNormals();
  return geometry;
}
"})
