result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/supershape.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { superRadius, buildSupershape } from '../src/supershape.js';

// Sphere preset: m = 0 makes both profiles constant, so the spherical
// product degenerates to a perfect unit sphere.
const SPHERE = { m: 0, n1: 1, n2: 1, n3: 1 };

describe('superRadius', () => {
  it('is angle-independent for m = 0, n1 = n2 = n3 = 1', () => {
    // Documented: with m = 0 the inner sum is the constant 1 + 0 = 1
    // (cos(0) = 1, sin(0) = 0), so r = 1^(-1/1) = 1 for every angle.
    const angles = [];
    for (let i = 0; i <= 100; i++) {
      angles.push(-Math.PI + (2 * Math.PI * i) / 100);
    }
    const reference = superRadius(angles[0], SPHERE);
    expect(reference).toBeCloseTo(1, 12);
    for (const a of angles) {
      expect(superRadius(a, SPHERE)).toBeCloseTo(reference, 9); // within 1e-9
    }
  });

  it('has period PI/2 for m = 4 (with symmetric n2 == n3)', () => {
    // For m = 4 the argument m*angle/4 shifts by PI/2 when angle does,
    // swapping |cos| and |sin|; with n2 = n3 the radius is exactly
    // periodic in PI/2.
    const p = { m: 4, n1: 1, n2: 1, n3: 1 };
    for (let i = 0; i < 64; i++) {
      const x = -Math.PI / 2 + (Math.PI * (i + 0.5)) / 64;
      expect(superRadius(x + Math.PI / 2, p)).toBeCloseTo(
        superRadius(x, p),
        9, // within 1e-9
      );
    }
  });
});

describe('buildSupershape', () => {
  it('produces a sphere when m = 0 and all radii are constant', () => {
    const geometry = buildSupershape(SPHERE, SPHERE, { segs: 48 });
    const pos = geometry.getAttribute('position');
    const radii = new Array(pos.count);
    let mean = 0;
    for (let i = 0; i < pos.count; i++) {
      const r = new THREE.Vector3().fromBufferAttribute(pos, i).length();
      radii[i] = r;
      mean += r;
    }
    mean /= pos.count;
    for (const r of radii) {
      expect(Math.abs(r - mean)).toBeLessThan(1e-6);
    }
  });

  it('has vertexCount = 6 * segs * segs positions (non-indexed)', () => {
    // Documented formula: (segs+1)^2 grid points -> segs^2 quads ->
    // 2 triangles per quad -> 6 vertices each.
    for (const segs of [4, 16]) {
      const geometry = buildSupershape(SPHERE, SPHERE, { segs });
      const pos = geometry.getAttribute('position');
      expect(geometry.index).toBeNull();
      expect(pos.count).toBe(6 * segs * segs);
    }
  });

  it('emits only finite positions for the spiky preset m=7, n1=0.2, n2=n3=1.7', () => {
    const spiky = { m: 7, n1: 0.2, n2: 1.7, n3: 1.7 };
    const geometry = buildSupershape(spiky, spiky, { segs: 64 });
    const pos = geometry.getAttribute('position');
    expect(pos.count).toBeGreaterThan(0);
    for (let i = 0; i < pos.count * 3; i++) {
      expect(Number.isFinite(pos.array[i])).toBe(true);
    }
    // Normals were computed and are finite too.
    const normals = geometry.getAttribute('normal');
    expect(normals).toBeDefined();
    for (let i = 0; i < normals.count * 3; i++) {
      expect(Number.isFinite(normals.array[i])).toBe(true);
    }
  });

  it('is deterministic: two identical calls produce identical buffers', () => {
    const params = { m: 5, n1: 0.3, n2: 1.7, n3: 1.7 };
    const g1 = buildSupershape(params, params, { segs: 32 });
    const g2 = buildSupershape(params, params, { segs: 32 });
    const p1 = g1.getAttribute('position').array;
    const p2 = g2.getAttribute('position').array;
    expect(p1.length).toBe(p2.length);
    for (let i = 0; i < p1.length; i++) {
      expect(p1[i]).toBe(p2[i]); // bitwise identical
    }
  });
});
"})
